{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name IN ('BasicController.queryForTravel','POST /api/v1/basicservice/basic/travel','BasicController.queryForTravels') GROUP BY span_name, attr_span_kind ORDER BY span_name",
          "claim": "queryForTravel server and internal spans have p95 about 1.76s, while the plural queryForTravels path stays near 15ms."
        },
        {
          "kind": "trace",
          "sql": "WITH b AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravel' AND duration>1e9 LIMIT 1) SELECT s.service_name, s.span_name, s.attr_span_kind, s.duration/1e6 ms, s.time FROM abnormal_traces s JOIN b ON s.trace_id=b.trace_id ORDER BY s.time",
          "claim": "In a slow trace, queryForTravel starts about 1.7s before its first downstream GET call; the gap is inside basic-service itself."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name='ts-basic-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory_limit_utilization','container.memory.page_faults') GROUP BY ALL",
          "claim": "Basic-service CPU and memory stay low during the incident, so resource saturation does not explain the delay."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE (service_name='ts-travel-service' AND span_name IN ('POST /api/v1/travelservice/trip_detail','POST')) OR (service_name='ts-basic-service' AND span_name='POST /api/v1/basicservice/basic/travel') GROUP BY ALL ORDER BY service_name, span_name",
          "claim": "Travel-service's client calls to basic and its trip_detail server span both reach about 1.76-1.79s p95, matching basic's slowdown."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name IN ('TravelPlanController.getByMinStation','POST /api/v1/travelplanservice/travelPlan/minStation') GROUP BY ALL",
          "claim": "Travel-plan minStation handling reaches about 1.3s p95 in abnormal, versus about 33ms in normal, while its client call waits on travel-service."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name IN ('POST /api/v1/preserveservice/preserve','POST') GROUP BY ALL",
          "claim": "Preserve-service's preserve server span and its client call to travel-service rise to about 3.6s and 1.8s p95."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/preserveservice/preserve' GROUP BY ALL",
          "claim": "The user-facing preserve request at ts-ui-dashboard rises to about 3.6s p95 in abnormal, versus about 160ms in normal."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/travelplanservice/travelPlan/minStation' GROUP BY ALL",
          "claim": "The user-facing minStation request at ts-ui-dashboard rises to about 1.3s p95, versus about 35ms in normal."
        }
      ]
    }
  ]
}
